    # where at each node (1 < v < n): sum of incoming = sum of outgoing

    # Use BFS from node 1 to get topological order (no cycles possible)
    parent = [0] * (n + 1)
    order = []
    queue = deque([1])
    visited = [False] * (n + 1)
    visited[1] = True

