def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    if m == 0 or n <= 1:
        return "0\n"

    edges = []
    for line in lines[1:]:
        line = line.strip()
        if line:
            edges.append(tuple(map(int, line.split())))

    # Count needed merges based on cycles in the graph
    # Each connected component needs to be made into a tree (caterpillar)

    parent = list(range(n + 1))
    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx
            return True
        return False

    for a, b in edges:
        union(a, b)

    # Count edges per component
    comp_edges = {}
    comp_verts = {}

    for a, b in edges:
        r = find(a)
        comp_edges[r] = comp_edges.get(r, 0) + 1
        comp_verts[r] = comp_verts.get(r, set())
        comp_verts[r].add(a)
        comp_verts[r].add(b)

    total_merges = 0
    for r in comp_edges:
        e = comp_edges[r]
        v = len(comp_verts[r])
        # Need v-1 edges for a tree
        total_merges += max(0, e - (v - 1))

    return str(total_merges) + '\n'

