import sys

def solution(input_str):
    # Read input from string
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, t = map(int, lines[0].split())

    # Parse queries
    queries = []
    for i in range(1, len(lines)):
        if i >= t + 1:
            break
        parts = lines[i].split()
        if len(parts) >= 2:
            x, y = int(parts[0]), int(parts[1])
            queries.append((x, y))

    # Handle n = 0
    if n == 0:
        return '\n'.join('0' for _ in queries)

    # Simulation approach: ants spread out and stop when each location has < 4 ants
    # Use a dict to track ant counts at positions
    locations = defaultdict(int)
    locations[(0, 0)] = n

    # Process iterations until no more splits possible
    # Since the diameter of the final pattern is O(log n), this converges quickly
    while True:
        # Find positions with >= 4 ants
        to_split = {}
        for loc, count in locations.items():
            if count >= 4:
                to_split[loc] = count

        if not to_split:
            break

        # New locations dict
        new_locations = defaultdict(int)

        for loc, count in to_split.items():
            # Keep count - 4 at this location
            remaining = count - 4
            if remaining > 0:
                new_locations[loc] = remaining

            # Send 1 ant to each of the 4 neighbors
            x, y = loc
            neighbors = [(x+1, y), (x-1, y), (x, y+1), (x, y-1)]
            for nx, ny in neighbors:
                new_locations[(nx, ny)] += 1

        locations = new_locations

    # Answer queries
    results = []
    for x, y in queries:
        results.append(str(locations.get((x, y), 0)))

    return '\n'.join(results)


