def check_axis_square(matrix, r, c, size, n, m):
    """Check if there's an axis-aligned square at (r,c) with given size."""
    if size < 2 or r + size > n or c + size > m:
        return False

    # Check top row (must be all 1s)
    if not all(matrix[r][c + i] == 1 for i in range(size)):
        return False
    # Check bottom row (must be all 1s)
    if not all(matrix[r + size - 1][c + i] == 1 for i in range(size)):
        return False
    # Check left column (must be all 1s)
    if not all(matrix[r + i][c] == 1 for i in range(size)):
        return False
    # Check right column (must be all 1s)
    if not all(matrix[r + i][c + size - 1] == 1 for i in range(size)):
        return False

    # Check all neighbors of border cells are 0 (can't touch foreign 1s)
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            for i in range(size):
                # Top row neighbors
                nr, nc = r + dr, c + i + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if matrix[nr][nc] == 1:
                        return False
                # Bottom row neighbors
                nr, nc = r + size - 1 + dr, c + i + dc
