    return True


def check_diagonal_square(matrix, r, c, size, n, m):
    """Check if there's a diagonal square at (r,c) with given size."""
    if size < 2 or r + size > n or c + size > m:
        return False

    # For a diagonal square of side 'size', check the diamond border
    # Top, right, bottom, left points
    if matrix[r][c] != 1:
        return False
    if matrix[r + size - 1][c + size - 1] != 1:
        return False
    if matrix[r + size - 1][c] != 1:
        return False
    if matrix[r][c + size - 1] != 1:
        return False

    # Check sides of the diamond (exclude corners to avoid double counting)
    for i in range(1, size - 1):
        if matrix[r][c + size - 1 - i] == 0:  # Top side
