def solve(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    targets = list(map(int, lines[1].split()))

    def count_prime_factors(x):
        if x == 1:
            return 0
        count = 0
        d = 2
        while d * d <= x:
            while x % d == 0:
                count += 1
                x //= d
            d += 1
        if x > 1:
            count += 1
        return count

    memo = {}

    # Precompute divisibility: i covers j if targets[i] % targets[j] == 0
    cover = [[False] * n for _ in range(n)]
    for i in range(n):
        cover[i][i] = True
        for j in range(n):
            if i != j and targets[i] % targets[j] == 0:
                cover[i][j] = True

    def dp(mask):
        if mask == 0:
            return 0
        if mask in memo:
            return memo[mask]

        cnt = bin(mask).count('1')
        if cnt == 1:
            i = (mask & -mask).bit_length() - 1
            return count_prime_factors(targets[i])

        best = float('inf')

        for i in range(n):
            if mask & (1 << i):
                covered_mask = 0
                for j in range(n):
                    if cover[i][j] and (mask & (1 << j)):
                        covered_mask |= (1 << j)

                remaining = mask & ~covered_mask
                remaining_cost = dp(remaining)
                total = remaining_cost + count_prime_factors(targets[i]) - 1
                if total < best:
                    best = total

        memo[mask] = best
        return best

    full_mask = (1 << n) - 1
    return str(dp(full_mask)) + '\n'

