def compute_solution(n, m, edges):
    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)

    # Floyd-Warshall or BFS from each node for shortest paths
    # Since all edges have weight 1, BFS is optimal
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        # BFS from start
        d = [float('inf')] * (n + 1)
        d[start] = 0
        q = deque([start])

        while q:
            u = q.popleft()
            for v in adj[u]:
                if d[v] == float('inf'):
                    d[v] = d[u] + 1
                    q.append(v)

        dist[start] = d

    # Find 4 cities that maximize the total distance
    best_path = None
    max_total = -1

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
                continue
            if dist[i][j] == float('inf'):
                continue
            for k in range(1, n + 1):
                if k == i or k == j:
                    continue
                if dist[j][k] == float('inf'):
                    continue
                for l in range(1, n + 1):
                    if l == i or l == j or l == k:
                        continue
                    if dist[k][l] == float('inf'):
                        continue

                    total = dist[i][j] + dist[j][k] + dist[k][l]
                    if total > max_total:
                        max_total = total
                        best_path = (i, j, k, l)

    return f"{best_path[0]} {best_path[1]} {best_path[2]} {best_path[3]}"

