def solution(input_str):
    lines = input_str.strip().split('\n')
    n, r = int(lines[0].split()[0]), int(lines[0].split()[1])

    def valid(x, y):
        return x*x + y*y <= r*r

    def objective(points):
        total = 0
        for i in range(n):
            for j in range(i + 1, n):
                dx = points[i][0] - points[j][0]
                dy = points[i][1] - points[j][1]
                total += dx*dx + dy*dy
        return total

    def random_valid_point():
        attempts = 0
        while attempts < 1000:
            x = random.randint(-r, r)
            y = random.randint(-r, r)
            if valid(x, y):
                return (x, y)
            attempts += 1
        return (0, 0)

    # Strategy: try multiple diverse starting configurations
    configs = []

    # Config 1: Random points
    for _ in range(10):
        pts = [random_valid_point() for _ in range(n)]
        configs.append(pts)

    # Config 2: Points on circle boundary at cardinal directions
    boundary_points = []
    for angle in [0, math.pi/2, math.pi, 3*math.pi/2]:
        x = int(round(r * math.cos(angle)))
        y = int(round(r * math.sin(angle)))
        if valid(x, y):
            boundary_points.append((x, y))

    for i in range(n):
        configs.append(boundary_points[i % len(boundary_points)] if boundary_points else (random_valid_point()))

    # Config 3: Only on x-axis extreme points
    x_axis_extremes = []
    for sign in [-1, 1]:
        if valid(sign*r, 0):
            x_axis_extremes.append((sign*r, 0))
    configs.append(x_axis_extremes * max(1, n//2))

    # Config 4: Only on y-axis extreme points
    y_axis_extremes = []
    for sign in [-1, 1]:
        if valid(0, sign*r):
            y_axis_extremes.append((0, sign*r))
    configs.append(y_axis_extremes * max(1, n//2))

    best_score = -1
    best_points = []

    for start_config in configs:
        score = objective(start_config)
        if score > best_score:
            best_score = score
            best_points = start_config

        # Local optimization: try to improve
        improved = True
        while improved:
            improved = False
            for i in range(n):
                # Try replacing with boundary point
                for angle in [0, math.pi/4, math.pi/2, 3*math.pi/4, math.pi, 5*math.pi/4, 3*math.pi/2, 7*math.pi/4]:
                    x = int(round(r * math.cos(angle)))
                    y = int(round(r * math.sin(angle)))
                    if valid(x, y):
                        old_pt = best_points[i]
                        best_points[i] = (x, y)
                        new_score = objective(best_points)
                        if new_score > score:
                            score = new_score
                            improved = True
                        else:
                            best_points[i] = old_pt
                # Try random valid replacement
                new_pt = random_valid_point()
                old_pt = best_points[i]
                best_points[i] = new_pt
                new_score = objective(best_points)
                if new_score > score:
                    score = new_score
                    improved = True
                else:
                    best_points[i] = old_pt

    # Output result
    result = [str(best_score)]
    for x, y in best_points:
        result.append(f"{x} {y}")
    return "\n".join(result) + "\n"

