import os

def point_in_convex_polygon(point, polygon):
    """
    Check if point is strictly inside convex polygon using winding number method.
    point = (x, y), polygon is list of (x, y) vertices in order
    """
    x, y = point
    n = len(polygon)
    winding = 0.0

    for i in range(n):
        x1, y1 = polygon[i]
        x2, y2 = polygon[(i + 1) % n]

        if y1 <= y < y2:
            if x < x2 - y2 * (x2 - x1) / (y2 - y1) if y2 != y1 else x1:
                winding += 1
        elif y2 < y <= y1:
            if x < x2 - y2 * (x2 - x1) / (y2 - y1) if y2 != y1 else x1:
                winding -= 1

    return winding != 0

