    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    l, r = map(int, lines[1].split())

    results = []

    for x1 in range(1, n + 1):
        found = False
        # For efficiency, we can limit y1 search
        # P = x1 * y1 must be in [l, r], so y1 must be in [ceil(l/x1), floor(r/x1)]
        y1_min = (l + x1 - 1) // x1  # ceil(l/x1)
        y1_max = min(m, r // x1)      # min(m, floor(r/x1))

        for y1 in range(y1_min, y1_max + 1):
            P = x1 * y1

            # Find x2 > x1 such that x2 divides P
            # and y2 = P/x2 < y1 (which is always true if x2 > x1)
            # We want smallest valid x2 for efficiency
            for x2 in range(x1 + 1, n + 1):
                if P % x2 == 0:
                    y2 = P // x2
                    if y2 < y1:
                        results.append(f"{x1} {y1} {x2} {y2}")
                        found = True
                        break
            if found:
                break

        if not found:
            results.append("-1")

    return '\n'.join(results)

