    n = int(n_str)
    k = int(k_str)

    MOD = 10**9 + 7

    if n == 1:
        return "0"

    if k == 1:
        return str((n - 1) ** 2 % MOD)

    N = n - 1
    k_inv = pow(k, MOD - 2, MOD)
    x_i = k_inv

    ans = 0
    for i in range(1, N + 1):
        term = ((2 * i - 1) * x_i) % MOD
        ans = (ans + term) % MOD
        x_i = (x_i * k_inv) % MOD

