def solution(input_str):
    lines = input_str.strip().split('\n')
    n, q = map(int, lines[0].split())

    points = []
    for i in range(1, n+1):
        parts = lines[i].split()
        points.append((int(parts[0]), int(parts[1])))

    edges = []
    for i in range(n):
        x1, y1 = points[i]
        x2, y2 = points[(i+1)%n]
        edges.append((x1, y1, x2, y2))

    y_coords = sorted(set(y for x, y in points))

    def get_x_at(y, e):
        x1, y1, x2, y2 = e
        if abs(y1 - y2) < 1e-9:
            return None
        t = (y - y1) / (y2 - y1)
        return x1 + t * (x2 - x1)

    def compute_folded_area(f):
        total_area = 0.0

        for j in range(len(y_coords) - 1):
            y1, y2 = y_coords[j], y_coords[j+1]
            mid_y = (y1 + y2) / 2

            xs = []
            for e in edges:
                x1, y1_e, x2, y2_e = e
                min_y = min(y1_e, y2_e)
                max_y = max(y1_e, y2_e)

                if min_y <= y2 and max_y >= y1:
                    x = get_x_at(mid_y, e)
                    if x is not None:
                        xs.append(x)

            if len(xs) >= 2:
                xs_sorted = sorted(xs)
                x_left = xs_sorted[0]
                x_right = xs_sorted[-1]

                width_after_folding = 0.0

                if x_left >= f:
                    width_after_folding = x_right - x_left
                elif x_right <= f:
                    width_after_folding = 0.0
                else:
                    reflected_x_left = 2 * f - x_left
                    if reflected_x_left <= x_right:
                        width_after_folding = x_right - f
                    else:
                        width_after_folding = reflected_x_left - f

                total_area += width_after_folding * (y2 - y1)

        return total_area

    output_lines = []
    for i in range(n+1, n+1+q):
        f = int(lines[i].strip())
        area = compute_folded_area(f)
        output_lines.append(f"{area:.10f}")

    return '\n'.join(output_lines)

