    from functools import lru_cache

    # Sort of state: current position, mask of visited planets (relative to some frame)
    # But absolute positions matter, so we need to be clever.

    # Key observation: For small k and m, we can use the structure.

    # Use memoization with the set of visited planets as a frozenset
    def count_from(current, visited_set):
