        max_reach = min(n, current + m)

        for next_pos in range(1, max_reach + 1):
            if next_pos not in visited_set:
                total = (total + count_from(next_pos, visited_set | {next_pos})) % MOD

        return total

    total = 0
    for start in range(1, n + 1):
        total = (total + count_from(start, {start})) % MOD

    return total

