def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "-1\n"

    n = int(lines[0])
    a_str = lines[1]
    if not a_str.strip():
        # Try reading from next line if second line is empty
        for i in range(2, len(lines)):
            if lines[i].strip():
                a_str = lines[i]
                break

    a = list(map(int, a_str.split()))
    a = sorted(a)

    if not a:
        return "-1\n"

    # Check if a valid prairie partition
    def is_prairie_partition(seq):
        if len(seq) == 0:
            return False
        n_seq = len(seq)

        # First element must be 1 (special case: if n_seq=1, any positive integer works as r)
        if n_seq == 1:
            if seq[0] == 1:
                return True
            return False

        # For length >= 2: first element must be 1, rest must be powers of 2: 1, 2, 4, 8...
        # Actually, the pattern is: [1, 2, 4, ..., 2^(k-1), r]
        # So elements 0 to n_seq-2 should be 1, 2, 4, ..., 2^(n_seq-2)
        if seq[0] != 1:
            return False

        for i in range(1, n_seq - 1):
            expected = 1 << (i - 1)  # 2^(i-1)
            if seq[i] != expected:
                return False

        # Last element r must satisfy: 1 <= r <= 2^(n_seq-2)
        if n_seq >= 2:
            max_r = 1 << (n_seq - 2)
            if seq[-1] < 1 or seq[-1] > max_r:
                return False

        return True

    # DP: dp[i][k] = can partition first i elements into exactly k valid prairie partitions
    results = []

    for m in range(1, n + 1):
        dp = [[False] * (m + 1) for _ in range(n + 1)]
        dp[0][0] = True

        possible_for_m = True

        for i in range(1, n + 1):
            for k in range(1, m + 1):
                for j in range(i):
                    if dp[j][k - 1]:
                        # Check if a[j:i] is a valid prairie partition
                        sub = a[j:i]
                        if is_prairie_partition(sub):
                            dp[i][k] = True
                            break
                if not dp[i][k]:
                    continue

        if dp[n][m]:
            results.append(m)

    if results:
        results.sort()
        return " ".join(map(str, results)) + "\n"
    else:
        return "-1\n"


